function plotRect(p,left=p.marginLeft??47,right=p.marginRight??12,top=p.marginTop??29,bottom=p.marginBottom??37){return{x:left,y:top,w:Math.max(10,p.w-left-right),h:Math.max(10,p.h-top-bottom)}}
function scales(p,rawX,rawY,r=plotRect(p)){
 const xd=[p.xMin??rawX[0],p.xMax??rawX[1]],yd=[p.yMin??rawY[0],p.yMax??rawY[1]];
 return{r,xd,yd,X:v=>r.x+(v-xd[0])/(xd[1]-xd[0]||1)*r.w,Y:v=>r.y+r.h-(v-yd[0])/(yd[1]-yd[0]||1)*r.h};
}
