function render(){const svg=$('figure');svg.replaceChildren();svg.setAttribute('viewBox',`0 0 ${state.canvasW} ${state.canvasH}`);svg.setAttribute('width',state.canvasW);svg.setAttribute('height',state.canvasH);svg.style.background=state.background;for(const p of state.panels){if(!p.visible)continue;const g=el('g',{class:`panel${p.id===state.selected?' selected':''}`,transform:`translate(${p.x} ${p.y})`});g.dataset.id=p.id;g.append(el('rect',{class:'panel-border',x:0,y:0,width:p.w,height:p.h,rx:p.panelRadius,style:`fill:${p.panelBg};fill-opacity:${p.panelBgAlpha};stroke:${p.panelBorder};stroke-width:${p.panelBorderWidth}`}));g.append(el('rect',{class:'panel-hit',x:0,y:0,width:p.w,height:p.h,rx:p.panelRadius,'data-panel':p.id,'data-drag':'panel'}));renderChart(g,p);textNode(g,p,'letter',p.letter,4+p.letterDx,15+p.letterDy,{anchor:'start',size:p.letterSize,fill:p.letterColor,weight:'bold'});textNode(g,p,'title',p.title,p.w/2+p.titleDx,17+p.titleDy,{anchor:p.titleAlign,size:p.titleSize,fill:p.titleColor});g.append(el('rect',{class:'resize-handle',x:p.w-8,y:p.h-8,width:8,height:8,'data-panel':p.id,'data-drag':'resize'}));svg.append(g)}bindSvg();syncControls();}
