const panel=id=>state.panels.find(p=>p.id===id);
const panelNumberFields=['x','y','w','h','xTicks','yTicks','xCategoryAngle','marginLeft','marginRight','marginTop','marginBottom','panelBgAlpha','panelBorderWidth','panelRadius','titleDx','titleDy','letterDx','letterDy','xLabelDx','xLabelDy','yLabelDx','yLabelDy','panelTitleSize','panelLetterSize','labelSize','panelAxisSize','panelAxisWidth','tickLength','gridOpacity','panelLineWidth','panelPointSize','panelPointOpacity','boxAlpha','jitterWidth','barAlpha','fillAlpha','histogramBins'];
