const geometryKeys=['w','h','xMin','xMax','yMin','yMax','xTicks','yTicks','marginLeft','marginRight','marginTop','marginBottom','xLabelDx','xLabelDy','yLabelDx','yLabelDy'];
const identityKeys=new Set(['id','letter','title','x','y','visible']);
const DEFAULT_KEY='Macaque_E4_ML_saved_default_v1';
