function controls(){const options=state.panels.map(p=>`<option value="${p.id}">${p.letter} · ${p.title}</option>`).join('');$('panelSelect').innerHTML=options;$('copyFromPanel').innerHTML=options;$('colors').innerHTML=Object.entries(state.colors).map(([k,v])=>`<label>${k}<input type="color" data-color="${k}" value="${v}"></label>`).join('');$('panelSelect').onchange=e=>{state.selected=e.target.value;render()};$('copyPanelParameters').onclick=copyPanelParameters;$('panelTitle').oninput=e=>{panel(state.selected).title=e.target.value;render()};$('titleAlign').onchange=e=>{panel(state.selected).titleAlign=e.target.value;render()};for(const id of panelNumberFields)$(id).oninput=e=>{panel(state.selected)[panelKey(id)]=+e.target.value;render()};for(const id of panelColorFields)$(id).oninput=e=>{panel(state.selected)[id]=e.target.value;render()};for(const k of['xMin','xMax','yMin','yMax'])$(k).onchange=e=>{panel(state.selected)[k]=e.target.value===''?null:+e.target.value;render()};$('visible').onchange=e=>{panel(state.selected).visible=e.target.checked;render()};$('panelColor').oninput=e=>{panel(state.selected).color=e.target.value;render()};$('panelColor2').oninput=e=>{panel(state.selected).color2=e.target.value;render()};for(const k of['canvasW','canvasH','columns','gapX','gapY'])$(k).oninput=e=>{state[k]=+e.target.value;render()};for(const k of['titleSize','letterSize','axisSize','lineWidth','pointSize','pointOpacity'])$(k).oninput=e=>{state[k]=+e.target.value;state.panels.forEach(p=>p[k]=state[k]);render()};for(const k of['background','fontFamily'])$(k).oninput=e=>{state[k]=e.target.value;render()};document.querySelectorAll('[data-color]').forEach(n=>n.oninput=e=>{state.colors[e.target.dataset.color]=e.target.value;render()});$('applyAllTypography').onclick=()=>{const fs=+$('allFontSize').value,col=$('allTextColor').value,align=$('allTitleAlign').value,angle=+$('allCategoryAngle').value;state.panels.forEach(p=>Object.assign(p,{titleSize:fs,letterSize:fs,labelSize:fs,axisSize:fs,titleColor:col,letterColor:col,labelColor:col,tickColor:col,titleAlign:align,xCategoryAngle:angle}));render()};$('applyAllLines').onclick=()=>{const lw=+$('allLineWidth').value,a=+$('allFillAlpha').value;state.panels.forEach(p=>Object.assign(p,{axisWidth:lw,lineWidth:lw,barAlpha:a,boxAlpha:a,fillAlpha:a}));render()};$('fitAxes').onclick=()=>{Object.assign(panel(state.selected),{xMin:null,xMax:null,yMin:null,yMax:null});render()};$('front').onclick=()=>{const i=state.panels.findIndex(p=>p.id===state.selected);state.panels.push(state.panels.splice(i,1)[0]);render()};$('autoLayout').onclick=autoLayout;$('reset').onclick=()=>location.reload();$('setDefault').onclick=()=>{localStorage.setItem(DEFAULT_KEY,JSON.stringify(state));$('status').textContent='Current layout and styles saved as the default for this browser.'};$('factoryDefault').onclick=()=>{localStorage.removeItem(DEFAULT_KEY);location.reload()};$('exportSvg').onclick=exportSvg;$('exportPng').onclick=exportPng;$('exportTif').onclick=exportTif;$('exportPdf').onclick=exportPdf;$('exportLayout').onclick=()=>download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'Macaque_E4_ML_layout.json');$('importLayout').onchange=importLayout}
function autoLayout(){const vis=state.panels.filter(p=>p.visible),cols=state.columns,w=Math.floor((state.canvasW-40-state.gapX*(cols-1))/cols),rows=Math.ceil(vis.length/cols),h=Math.floor((state.canvasH-40-state.gapY*(rows-1))/rows);vis.forEach((p,i)=>Object.assign(p,{x:20+(i%cols)*(w+state.gapX),y:20+Math.floor(i/cols)*(h+state.gapY),w,h}));render()}
function svgText(){const clone=$('figure').cloneNode(true);clone.querySelectorAll('.panel-hit,.resize-handle').forEach(n=>n.remove());clone.querySelectorAll('.panel').forEach(n=>n.classList.remove('selected'));clone.setAttribute('xmlns',NS);return new XMLSerializer().serializeToString(clone)}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportSvg(){download(new Blob([svgText()],{type:'image/svg+xml'}),'Macaque_E4_ML_interactive_export.svg')}
async function raster(forceWhite=false){const dpi=+$('dpi').value,w=Math.round(+$('exportWidth').value*dpi),h=Math.round(w*state.canvasH/state.canvasW),img=new Image(),url=URL.createObjectURL(new Blob([svgText()],{type:'image/svg+xml'}));await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src=url});const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');if(forceWhite){x.fillStyle='#fff';x.fillRect(0,0,w,h)}x.drawImage(img,0,0,w,h);URL.revokeObjectURL(url);return c}
async function exportPng(){const c=await raster();c.toBlob(b=>download(b,`Macaque_E4_ML_${$('dpi').value}dpi.png`),'image/png')}
async function exportTif(){const c=await raster(true);download(tiff(c,+$('dpi').value),`Macaque_E4_ML_${$('dpi').value}dpi.tif`)}
async function exportPdf(){const c=await raster(true),blob=await new Promise(ok=>c.toBlob(ok,'image/jpeg',.98));download(pdf(new Uint8Array(await blob.arrayBuffer()),c.width,c.height,+$('exportWidth').value),'Macaque_E4_ML.pdf')}
function tiff(c,dpi){const{width:w,height:h}=c,img=c.getContext('2d').getImageData(0,0,w,h).data,n=14,ifd=8,bits=ifd+2+n*12+4,xres=bits+6,yres=xres+8,pixels=yres+8,bytes=new Uint8Array(pixels+w*h*3),v=new DataView(bytes.buffer);bytes[0]=73;bytes[1]=73;v.setUint16(2,42,true);v.setUint32(4,ifd,true);v.setUint16(ifd,n,true);let p=ifd+2;const e=(tag,type,count,value,short=false)=>{v.setUint16(p,tag,true);v.setUint16(p+2,type,true);v.setUint32(p+4,count,true);short?v.setUint16(p+8,value,true):v.setUint32(p+8,value,true);p+=12};e(256,4,1,w);e(257,4,1,h);e(258,3,3,bits);e(259,3,1,1,true);e(262,3,1,2,true);e(273,4,1,pixels);e(274,3,1,1,true);e(277,3,1,3,true);e(278,4,1,h);e(279,4,1,w*h*3);e(282,5,1,xres);e(283,5,1,yres);e(284,3,1,1,true);e(296,3,1,2,true);v.setUint32(p,0,true);[0,2,4].forEach(o=>v.setUint16(bits+o,8,true));v.setUint32(xres,dpi,true);v.setUint32(xres+4,1,true);v.setUint32(yres,dpi,true);v.setUint32(yres+4,1,true);for(let i=0,j=pixels;i<img.length;i+=4){bytes[j++]=img[i];bytes[j++]=img[i+1];bytes[j++]=img[i+2]}return new Blob([bytes],{type:'image/tiff'})}
function pdf(jpg,w,h,widthIn){const enc=new TextEncoder(),parts=[],offsets=[0],push=x=>parts.push(typeof x==='string'?enc.encode(x):x),pw=widthIn*72,ph=pw*h/w;push('%PDF-1.4\n');let len=parts.reduce((a,b)=>a+b.length,0);const obj=(id,body)=>{offsets[id]=len;const a=enc.encode(`${id} 0 obj\n${body}\nendobj\n`);parts.push(a);len+=a.length};obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=len;push(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${w} /Height ${h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);push(jpg);push('\nendstream\nendobj\n');len=parts.reduce((a,b)=>a+b.length,0);const content=`q\n${pw} 0 0 ${ph} 0 0 cm\n/Im0 Do\nQ`;obj(5,`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);const xref=len;push(`xref\n0 6\n0000000000 65535 f \n${offsets.slice(1).map(o=>String(o).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
function applyLayoutState(x){const byId=Object.fromEntries((x.panels??[]).map(p=>[p.id,p]));Object.assign(state,structuredClone(defaultState),x);state.colors={...defaultState.colors,...(x.colors??{})};state.panels=defaultState.panels.map(p=>({...p,...(byId[p.id]??{})}));if(!state.panels.some(p=>p.id===state.selected))state.selected=state.panels[0].id}
function importLayout(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{applyLayoutState(JSON.parse(r.result));controls();render()};r.readAsText(f)}
async function start(){try{const names=['supervised','supervised_summary','confusion','sensitivity','discovery','agreement','consensus','roc','pr','roc_pr_metrics','permutation','permutation_summary','metadata','train_importance','mdi','ablation'];const vals=await Promise.all(names.map(n=>load(`${n}.csv`)));D=Object.fromEntries(names.map((n,i)=>[n==='train_importance'?'trainImp':n==='permutation_summary'?'permSummary':n,vals[i]]));const saved=localStorage.getItem(DEFAULT_KEY);if(saved)applyLayoutState(JSON.parse(saved));controls();render();$('status').textContent=`Revalidated data loaded · 16 editable panels · ${saved?'saved default restored':'factory default active'} · export matches the current SVG preview`;}catch(e){$('status').textContent='Unable to load validation data: '+e.message}}
start();
